const {run}=require('/tmp/probe-sep/run.js');
// skip: 0x00 (impossible in argv), 0x5f (ambiguous under this parse), ASCII punct/ws tested individually
function testBatch(cps){
  const val = cps.map(c=>'a'+String.fromCodePoint(c)+'b').join('!');
  const r=run(val);
  if(r.code!==0) return {fail:'exit'+r.code+' '+r.err.slice(0,120)};
  let out=r.outStr;
  if(out.endsWith('\n')) out=out.slice(0,-1);
  const toks=out.split('_');
  const verdicts=[]; let i=0;
  for(const c of cps){
    if(i>=toks.length) return {fail:'ran out of tokens'};
    if(toks[i]==='a'){
      if(toks[i+1]!=='b') return {fail:'bad pair at cp '+c.toString(16)+' toks '+JSON.stringify(toks.slice(i,i+3))};
      verdicts.push([c,'SEP']); i+=2;
    } else {
      const t=toks[i];
      if(!(t.startsWith('a')&&t.endsWith('b')&&t.length>=3)) return {fail:'bad tok at cp '+c.toString(16)+' tok '+JSON.stringify(t)};
      verdicts.push([c,'NOT',t.slice(1,-1)]); i++;
    }
  }
  if(i!==toks.length) return {fail:'leftover tokens '+JSON.stringify(toks.slice(i))};
  return {verdicts};
}
function testIndividual(c){
  const r=run('a'+String.fromCodePoint(c)+'b');
  if(r.code!==0) return [c,'ERR',r.code+' '+r.err.slice(0,120)];
  let out=r.outStr; if(out.endsWith('\n')) out=out.slice(0,-1);
  if(out==='a_b') return [c,'SEP?'];
  if(out.startsWith('a')&&out.endsWith('b')) return [c,'NOT',out.slice(1,-1)];
  return [c,'ODD',Buffer.from(out,'utf8').toString('hex')];
}
function sweep(cps,label){
  const skip=new Set([0x00,0x5f]);
  const list=cps.filter(c=>!skip.has(c)&&!(c>=0xd800&&c<=0xdfff));
  const seps=[]; const fails=[];
  for(let k=0;k<list.length;k+=150){
    const chunk=list.slice(k,k+150);
    const res=testBatch(chunk);
    if(res.fail){ fails.push({chunk:[chunk[0].toString(16),chunk[chunk.length-1].toString(16)],fail:res.fail});
      // fallback individual
      for(const c of chunk){const v=testIndividual(c); if(v[1]!=='NOT') fails.push(v);}
      continue; }
    for(const v of res.verdicts) if(v[1]==='SEP') seps.push(v[0]);
  }
  console.log(label,'SEPS:',JSON.stringify(seps.map(c=>'U+'+c.toString(16).toUpperCase().padStart(4,'0'))),'tested',list.length);
  if(fails.length) console.log(label,'FAILS:',JSON.stringify(fails,null,1));
  return seps;
}
module.exports={sweep,testBatch,testIndividual};
if(require.main===module){
  const rng=(a,b)=>{const r=[];for(let i=a;i<=b;i++)r.push(i);return r;};
  sweep(rng(0x80,0xff),'latin1');
  sweep(rng(0x2000,0x206f),'genpunct');
  sweep(rng(0x2e00,0x2e7f),'suppl-punct');
  sweep(rng(0x3000,0x303f),'cjk-punct');
  sweep(rng(0xff00,0xff65),'fullwidth');
  sweep([0x1680,0x180e,0x0085,0xfeff,0x2028,0x2029,0x200b,0x00a0,0x202f,0x205f,0x3000,0x1c,0x1d,0x1e,0x1f],'misc');
}
EOF
